query GetPlayerEvents(
  $code: String!, $fightIDs: [Int]!, $startTime: Float!, $endTime: Float!
) {
  reportData {
    report(code: $code) {
      events(
        fightIDs: $fightIDs, dataType: Casts, startTime: $startTime,
        endTime: $endTime, limit: 5000, translate: true
      ) {
        data
        nextPageTimestamp
      }
    }
  }
}
